import requests.utils
from requests.utils import should_bypass_proxies

def domain_match(h, hostname):
    if h.startswith('.'):
        return hostname.endswith(h) or hostname == h[1:]
    return hostname == h or hostname.endswith('.' + h)

def should_bypass_proxies_fixed(url, no_proxy):
    import os
    from urllib.parse import urlparse

    def get_proxy(key):
        return os.environ.get(key) or os.environ.get(key.upper())

    if no_proxy is None:
        no_proxy = get_proxy("no_proxy")

    parsed = urlparse(url)
    hostname = parsed.hostname

    if hostname is None:
        return True

    if no_proxy:
        no_proxy_hosts = (host for host in no_proxy.replace(" ", "").split(",") if host)
        for host in no_proxy_hosts:
            if ':' in host:
                h, p = host.split(':', 1)
                if parsed.port is not None and str(parsed.port) == p and domain_match(h, hostname):
                    return True
            elif domain_match(host, hostname):
                return True

    return False

def test_no_proxy(url, no_proxy, expected):
    result = should_bypass_proxies_fixed(url, no_proxy)
    print(f"URL: {url:30} | NoProxy: {no_proxy:20} | Expected: {str(expected):5} | Result: {str(result):5} | {'PASS' if result == expected else 'FAIL'}")

print("Testing fixed implementation:")
test_no_proxy('http://example.com', 'example.com', True)
test_no_proxy('http://api.example.com', 'example.com', True)
test_no_proxy('http://myexample.com', 'example.com', False)
test_no_proxy('http://api.example.com', '.example.com', True)
test_no_proxy('http://example.com', '.example.com', True)
test_no_proxy('http://myexample.com', '.example.com', False)
test_no_proxy('http://example.com:80', 'example.com:80', True)
test_no_proxy('http://api.example.com:80', 'example.com:80', True)
test_no_proxy('http://myexample.com:80', 'example.com:80', False)
EOF

